List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File must be a valid existing file.");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges must not be null.");
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Assuming each line represents a snapshot and has a timestamp
            // This parsing logic needs to be adjusted based on actual file format
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                    snapshots.add(snapshot);
                    break;
                }
            }
        }
    }
    return snapshots;
}
